test "stress test randomized operations on larger dataset" {
    var file = try helpers.get_temp_file_path("test_stress_random_operations_large");
    defer file.deinit();

    var gpa = std.heap.DebugAllocator(.{}){};
    const allocator = gpa.allocator();
    var db = try Muscle.init(allocator, file.file_path);

    var arena = std.heap.ArenaAllocator.init(allocator);

    const table_name = "large_stress_test";

    try expect_success(try db.execute("create table large_stress_test (pk TEXT(2023) PRIMARY KEY, int_val INT, real_val REAL, text_val TEXT(500))", arena.allocator()));

    const get_insert_sql = struct {
        fn f(alloc: std.mem.Allocator, pk: []const u8, int_val: i64, real_val: f64, text_val: []const u8) ![]const u8 {
            // Generated keys and text contain only ASCII letters.
            return std.fmt.allocPrint(alloc, "INSERT INTO large_stress_test (pk, int_val, real_val, text_val) VALUES ('{s}', {d}, {d}, '{s}')", .{ pk, int_val, real_val, text_val });
        }
    }.f;

    const rng_impl: std.Random.IoSource = .{ .io = std.testing.io };
    const rng = rng_impl.interface();
    var inserted_keys = std.ArrayList([2023]u8).empty;
    var text_buffer: [500]u8 = undefined;

    // std.debug.print("Phase 1: Inserting 2000 random entries...\n", .{});
    for (0..2000) |i| {
        var key: [2023]u8 = undefined;
        for (&key) |*char| {
            char.* = 'A' + rng.uintLessThan(u8, 26);
        }

        // Generate random text value
        const text_len = rng.uintLessThan(usize, 400) + 100; // 100-499 chars
        for (text_buffer[0..text_len]) |*char| {
            char.* = 'a' + rng.uintLessThan(u8, 26);
        }

        // Check if key exists
        var exists = false;
        for (inserted_keys.items) |existing_key| {
            if (std.mem.eql(u8, &existing_key, &key)) {
                exists = true;
                break;
            }
        }

        const insert_response = try db.execute(try get_insert_sql(
            arena.allocator(),
            &key,
            @as(i64, rng.int(u63)),
            rng.float(f64),
            text_buffer[0..text_len],
        ), arena.allocator());

        if (exists) {
            assert(insert_response.is_error_result());
            assert(insert_response.err.code == error.DuplicateKey);
        } else {
            try expect_success(insert_response);
            try inserted_keys.append(arena.allocator(), key);

            // Validate every 100 insertions
            if (i % 100 == 0) {
                var metadata = try db.select_table_info(table_name, arena.allocator());
                try validate_btree(&metadata);
            }
        }
    }

    // std.debug.print("Phase 1 complete: {} unique keys inserted\n", .{inserted_keys.items.len});
    // std.debug.print("Phase 2: Random updates...\n", .{});
    for (0..inserted_keys.items.len) |i| {
        if (inserted_keys.items.len == 0) break;

        const random_index = rng.uintLessThan(usize, inserted_keys.items.len);
        const key_to_update = inserted_keys.items[random_index];

        // Generate new random values for the update
        const text_len = rng.uintLessThan(usize, 400) + 100; // 100-499 chars
        for (text_buffer[0..text_len]) |*char| {
            char.* = 'a' + rng.uintLessThan(u8, 26);
        }

        const update_sql = try std.fmt.allocPrint(arena.allocator(), "UPDATE large_stress_test SET int_val = {d}, real_val = {d}, text_val = '{s}' WHERE pk = '{s}'", .{ @as(i64, rng.int(u63)), rng.float(f64), text_buffer[0..text_len], key_to_update });
        const update_response = try db.execute(update_sql, arena.allocator());
        try expect_success(update_response);
        try std.testing.expectEqual(@as(usize, 1), update_response.rowCount());
        var offset: usize = 0;
        const affected = try serde.read_value(update_response.data.rows.items[0], &offset, .int);
        try std.testing.expectEqual(@as(i64, 1), affected.int);

        // Validate every 100 updates
        if (i % 100 == 0) {
            var metadata = try db.select_table_info(table_name, arena.allocator());
            try validate_btree(&metadata);
        }
    }

    // std.debug.print("Phase 2 complete: {} keys updated\n", .{inserted_keys.items.len});
    // std.debug.print("Phase 2: Random deletions...\n", .{});
    const delete_count = inserted_keys.items.len / 3;
    var deleted_count: usize = 0;

    for (0..delete_count) |i| {
        if (inserted_keys.items.len == 0) break;

        const random_index = rng.uintLessThan(usize, inserted_keys.items.len);
        const key_to_delete = inserted_keys.swapRemove(random_index);

        try delete_text_key(&db, arena.allocator(), table_name, &key_to_delete);

        deleted_count += 1;

        // Validate every 50 deletions
        if (i % 50 == 0) {
            var metadata = try db.select_table_info(table_name, arena.allocator());
            try validate_btree(&metadata);
        }
    }

    // std.debug.print("Phase 3 complete: {} keys deleted, {} keys remaining\n", .{ deleted_count, inserted_keys.items.len });
    // std.debug.print("Phase 4: Mixed operations...\n", .{});
    for (0..1000) |i| {
        const operation = rng.uintLessThan(u8, 3); // 0=insert, 1=delete, 2=insert

        if (operation == 1 and inserted_keys.items.len > 100) {
            // Delete operation
            const random_index = rng.uintLessThan(usize, inserted_keys.items.len);
            const key_to_delete = inserted_keys.swapRemove(random_index);

            try delete_text_key(&db, arena.allocator(), table_name, &key_to_delete);
        } else {
            // Insert operation
            var key: [2023]u8 = undefined;
            for (&key) |*char| {
                char.* = 'A' + rng.uintLessThan(u8, 26);
            }

            // Generate random text value
            const text_len = rng.uintLessThan(usize, 400) + 100;
            for (text_buffer[0..text_len]) |*char| {
                char.* = 'a' + rng.uintLessThan(u8, 26);
            }

            // Check if key exists
            var exists = false;
            for (inserted_keys.items) |existing_key| {
                if (std.mem.eql(u8, &existing_key, &key)) {
                    exists = true;
                    break;
                }
            }

            const insert_response = try db.execute(try get_insert_sql(
                arena.allocator(),
                &key,
                @as(i64, rng.int(u63)),
                rng.float(f64),
                text_buffer[0..text_len],
            ), arena.allocator());

            if (exists) {
                assert(insert_response.is_error_result());
                assert(insert_response.err.code == error.DuplicateKey);
            } else {
                try expect_success(insert_response);
                try inserted_keys.append(arena.allocator(), key);
            }
        }

        // Validate every 100 operations
        if (i % 100 == 0) {
            var metadata = try db.select_table_info(table_name, arena.allocator());
            try validate_btree(&metadata);
        }
    }

    // std.debug.print("Phase 4 complete: {} keys remaining\n", .{inserted_keys.items.len});
    // std.debug.print("Phase 5: Rapid insertions stress test...\n", .{});
    for (0..500) |i| {
        var key: [2023]u8 = undefined;
        // Use a more predictable pattern to ensure uniqueness
        const base_char = 'A' + @as(u8, @intCast(i % 26));
        for (&key, 0..) |*char, j| {
            char.* = base_char + @as(u8, @intCast((j + i) % 26));
        }

        const text_len = 200;
        for (text_buffer[0..text_len]) |*char| {
            char.* = 'z' - @as(u8, @intCast(i % 26));
        }

        const insert_response = try db.execute(try get_insert_sql(
            arena.allocator(),
            &key,
            @as(i64, @intCast(i)),
            @as(f64, @floatFromInt(i)) * 3.14159,
            text_buffer[0..text_len],
        ), arena.allocator());

        if (!insert_response.is_error_result()) {
            try inserted_keys.append(arena.allocator(), key);
        }

        // Validate every 50 insertions
        if (i % 50 == 0) {
            var metadata = try db.select_table_info(table_name, arena.allocator());
            try validate_btree(&metadata);
        }
    }

    // Final comprehensive validation
    var final_metadata = try db.select_table_info(table_name, arena.allocator());
    try validate_btree(&final_metadata);

    arena.deinit();
    db.deinit();
    const deinit_status = gpa.deinit();
    if (deinit_status == .leak) {
        @panic("LEAK DETECTED");
    }
}

fn delete_text_key(db: *Muscle, allocator: std.mem.Allocator, table_name: []const u8, key: []const u8) !void {
    const sql = try std.fmt.allocPrint(allocator, "DELETE FROM {s} WHERE pk = '{s}'", .{ table_name, key });
    defer allocator.free(sql);
    const result = try db.execute(sql, allocator);
    try expect_success(result);
    try std.testing.expectEqual(@as(usize, 1), result.columnCount());
    try std.testing.expectEqualStrings("rows_affected", result.data.columns[0].name);
    try std.testing.expectEqualDeep(muscle.DataType.int, result.data.columns[0].data_type);
    try std.testing.expectEqual(@as(usize, 1), result.rowCount());
    var offset: usize = 0;
    const count = try serde.read_value(result.data.rows.items[0], &offset, .int);
    try std.testing.expectEqual(@as(i64, 1), count.int);
    try std.testing.expectEqual(result.data.rows.items[0].len, offset);
}

fn expect_success(result: muscle.query_result.QueryResult) !void {
    if (result == .err) std.debug.print("SQL query failed: {s}: {s}\n", .{ @errorName(result.err.code), result.err.message });
    try std.testing.expect(result == .data);
}

fn validate_btree(metadata: *const muscle.database.SelectTableMetadataResult) !void {
    var allocator = metadata.pages.allocator;
    const L = struct {
        data: struct {
            min_key: ?[]const u8,
            max_key: ?[]const u8,
            page: muscle.PageNumber,
        },
        node: std.DoublyLinkedList.Node,
    };

    var queue = std.DoublyLinkedList{};
    const primary_key_data_type = metadata.table_columns.items[0].data_type;

    // if root is empty then it should be a leaf node
    if (metadata.pages.getPtr(metadata.root_page)) |page| {
        if (page.content_size == 0) {
            assert(page.cells.items.len == 0);
            assert(page.right_child == 0);
            assert(metadata.pages.count() == 1);
        } else {
            var l = try allocator.create(L);
            l.data = .{
                .min_key = null,
                .max_key = null,
                .page = page.page,
            };
            queue.append(&l.node);
        }
    } else unreachable;

    while (queue.popFirst()) |node| {
        const l: *L = @fieldParentPtr("node", node);
        defer allocator.destroy(l);

        const data = l.data;
        const page_meta = metadata.pages.getPtr(data.page).?;
        const is_leaf = page_meta.right_child == 0;

        // every page should have atleast one cell
        assert(page_meta.cells.items.len > 0);

        // need to check that all childrens are unique
        var child_pages = std.ArrayList(muscle.PageNumber).empty;
        defer child_pages.deinit(allocator);

        // append right child to child_pages
        if (!is_leaf) try child_pages.append(allocator, page_meta.right_child);

        for (page_meta.cells.items, 0..) |cell, slot| {
            const curr_key = cell.key;

            // check that all child pages and unique
            if (!is_leaf) {
                for (child_pages.items) |n| assert(n != cell.left_child);
                try child_pages.append(allocator, cell.left_child);
            }

            // assert that keys are in order
            if (slot > 0) {
                assert(serde.compare_serialized_bytes(
                    primary_key_data_type,
                    page_meta.cells.items[slot - 1].key,
                    curr_key,
                ) == std.math.Order.lt);
            }

            if (data.min_key) |min_key| {
                if (!(serde.compare_serialized_bytes(primary_key_data_type, min_key, curr_key) == std.math.Order.lt)) {
                    const len_a = std.mem.readInt(u16, curr_key[0..@sizeOf(u16)], .little);
                    const len_b = std.mem.readInt(u16, min_key[0..@sizeOf(u16)], .little);

                    if (primary_key_data_type == .bin or primary_key_data_type == .txt) {
                        std.debug.print(
                            "curr_key: {d}#{s} \nmin_key: {d}#{s}\n\n",
                            .{ len_a, curr_key[@sizeOf(u16)..12], len_b, min_key[@sizeOf(u16)..12] },
                        );
                    } else {
                        std.debug.print(
                            "curr_key: {d}#{s} \nmin_key: {d}#{s}\n\n",
                            .{ len_a, curr_key[@sizeOf(u16)..12], len_b, min_key[@sizeOf(u16)..12] },
                        );
                    }

                    assert(false);
                }
            }

            if (data.max_key) |max_key| {
                if (!(serde.compare_serialized_bytes(primary_key_data_type, curr_key, max_key).compare(.lte))) {
                    if (primary_key_data_type == .bin or primary_key_data_type == .txt) {
                        const len_a = std.mem.readInt(u16, curr_key[0..@sizeOf(u16)], .little);
                        const len_b = std.mem.readInt(u16, max_key[0..@sizeOf(u16)], .little);

                        if (primary_key_data_type == .bin or primary_key_data_type == .txt) {
                            std.debug.print(
                                "curr_key: {d}#{s} \nmin_key: {d}#{s}\n\n",
                                .{ len_a, curr_key[@sizeOf(u16)..12], len_b, max_key[@sizeOf(u16)..12] },
                            );
                        } else {
                            std.debug.print(
                                "curr_key: {d}#{s} \nmin_key: {d}#{s}\n\n",
                                .{ len_a, curr_key[@sizeOf(u16)..12], len_b, max_key[@sizeOf(u16)..12] },
                            );
                        }

                        assert(false);
                    } else {
                        // std.debug.print("curr_key: {s} \nmax_key: {s}\n\n", .{ curr_key, max_key });
                    }

                    assert(false);
                }
            }

            // For internal nodes validate cells left_child is non zero and push data inside the queue
            if (!is_leaf) {
                const pivot_cell = cell;
                const pivot_cell_slot = slot;

                // child is in the middle between pivot cell and cell before pivot cell.
                // for the left child all the keys must be less than or equal to pivot cell
                // And all the keys must be greater than one cell before pivot cell.

                assert(pivot_cell.left_child != 0);

                const next_min_key =
                    if (pivot_cell_slot > 0)
                        page_meta.cells.items[pivot_cell_slot - 1].key
                    else
                        data.min_key;

                const next_max_key = pivot_cell.key;

                // append child to queue
                const next = try allocator.create(L);
                next.data = .{
                    .min_key = next_min_key,
                    .max_key = next_max_key,
                    .page = cell.left_child,
                };
                queue.append(&next.node);
            } else {
                // for leaf nodes left_child should be zero
                assert(cell.left_child == 0);
            }

            // validate left and right pointers
            if (page_meta.left != 0) {
                const left = metadata.pages.getPtr(page_meta.left).?;
                assert(left.right == page_meta.page);
            }

            if (page_meta.right != 0) {
                const right = metadata.pages.getPtr(page_meta.right).?;
                assert(right.left == page_meta.page);
            }
        }

        // append right child to queue
        if (!is_leaf) {
            const min_key = page_meta.cells.items[page_meta.cells.items.len - 1].key;
            const max_key = data.max_key;

            const next = try allocator.create(L);
            next.data = .{
                .min_key = min_key,
                .max_key = max_key,
                .page = page_meta.right_child,
            };
            queue.append(&next.node);
        }
    }
}
